<script>document.addEventListener('DOMContentLoaded',()=>{const map=document.querySelector('[data-damage-map]'),input=document.querySelector('[data-damage-input]');let points=[],type='scratch';document.querySelectorAll('[data-damage-type]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-damage-type]').forEach(x=>x.classList.remove('active'));b.classList.add('active');type=b.dataset.damageType});const sync=()=>input.value=JSON.stringify(points);map?.addEventListener('click',e=>{if(e.target.classList.contains('damage-point')){points=points.filter(p=>String(p.id)!==e.target.dataset.id);e.target.remove();sync();return}const r=map.getBoundingClientRect(),p={id:Date.now(),x:+(((e.clientX-r.left)/r.width)*100).toFixed(2),y:+(((e.clientY-r.top)/r.height)*100).toFixed(2),type};points.push(p);const el=document.createElement('button');el.type='button';el.className='damage-point '+type;el.dataset.id=p.id;el.style.left=p.x+'%';el.style.top=p.y+'%';map.append(el);sync()})});</script>
